@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Dark SaaS — near-black canvas, subtle borders, one electric accent, tight type */
.theme-dark-saas {
  --bg: oklch(0.139 0.003 246.3);
  --surface: oklch(0.2 0.005 285);
  --surface-2: oklch(0.24 0.006 285);
  --fg: oklch(0.97 0.002 285);
  --fg-muted: oklch(0.649 0.015 262.4);
  --accent: oklch(0.62 0.23 274);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.72 0.15 200);
  --line: oklch(1 0 0 / 10%);
  --success: oklch(0.7 0.17 155);
  --warning: oklch(0.78 0.16 80);
  --danger: oklch(0.63 0.22 22);

  --radius: 0.5rem;
  --radius-sm: 0.375rem;
  --radius-lg: 0.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 1px 2px 0 oklch(0 0 0 / 45%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 65%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 75%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.035em;
  --label-transform: none;
  --label-tracking: 0em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-dark-saas h1,
.theme-dark-saas h2,
.theme-dark-saas h3 {
  letter-spacing: var(--tracking-display);
  font-weight: 600;
}

/* signature */
.theme-dark-saas { --font-ui: var(--font-display); }
.theme-dark-saas h1 { background: linear-gradient(180deg, var(--fg), var(--fg-muted)); -webkit-background-clip: text; background-clip: text; color: transparent; letter-spacing: -0.045em; }

/* depth */
.theme-dark-saas thead th { font-size: 0.72rem; font-weight: 500; text-transform: uppercase; letter-spacing: 0.06em; color: var(--fg-muted); background: var(--surface); border-bottom: 1px solid var(--line); }
.theme-dark-saas td { border-bottom: 1px solid oklch(1 0 0 / 6%); }
.theme-dark-saas tbody tr { transition: background-color 0.12s ease; }
.theme-dark-saas tbody tr:hover { background: oklch(1 0 0 / 3%); }
.theme-dark-saas input, .theme-dark-saas select, .theme-dark-saas textarea { background: oklch(0 0 0 / 25%); border: 1px solid var(--line); border-radius: var(--radius-sm); transition: border-color 0.15s ease, box-shadow 0.15s ease; }
.theme-dark-saas input:focus-visible, .theme-dark-saas select:focus-visible, .theme-dark-saas textarea:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px color-mix(in oklab, var(--accent) 22%, transparent); }
.theme-dark-saas kbd { font-family: var(--font-mono); font-size: 0.72em; padding: 0.15em 0.45em; background: var(--surface-2); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: var(--radius-sm); }
.theme-dark-saas a { color: var(--fg); text-decoration-color: oklch(1 0 0 / 25%); text-underline-offset: 3px; transition: color 0.12s ease, text-decoration-color 0.12s ease; }
.theme-dark-saas a:hover { color: var(--accent); text-decoration-color: var(--accent); }
.theme-dark-saas ::selection { background: color-mix(in oklab, var(--accent) 35%, transparent); }
.theme-dark-saas ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-dark-saas ::-webkit-scrollbar-track { background: transparent; }
.theme-dark-saas ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 14%); border-radius: var(--radius-pill); border: 2px solid var(--bg); }
.theme-dark-saas ::-webkit-scrollbar-thumb:hover { background: oklch(1 0 0 / 24%); }
.theme-dark-saas .label-caps { font-size: 0.72rem; color: var(--fg-muted); }
/* machined edge: 1px top highlight on raised surfaces */
.theme-dark-saas .themed-border { box-shadow: inset 0 1px 0 oklch(1 0 0 / 7%), var(--shadow-1); }
.theme-dark-saas button:active { transform: translateY(1px); }

/* alt mode: paper variant — same product, gallery lighting */
.theme-dark-saas.alt-mode {
  --accent: oklch(0.52 0.23 274);
  --accent-2: oklch(0.55 0.13 200);
  --bg: oklch(0.98 0.003 246.3);
  --surface: oklch(0.955 0.003 246.3);
  --surface-2: oklch(0.92 0.003 246.3);
  --fg: oklch(0.17 0.005 270);
  --fg-muted: oklch(0.46 0.01 270);
  --line: oklch(0.87 0.005 270);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}
.theme-dark-saas.alt-mode td { border-bottom-color: oklch(0 0 0 / 7%); }
.theme-dark-saas.alt-mode tbody tr:hover { background: oklch(0 0 0 / 3%); }
.theme-dark-saas.alt-mode input, .theme-dark-saas.alt-mode select, .theme-dark-saas.alt-mode textarea { background: oklch(1 0 0 / 70%); }
.theme-dark-saas.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0 0 0 / 18%); border-color: var(--bg); }
.theme-dark-saas.alt-mode a { text-decoration-color: oklch(0 0 0 / 25%); }
.theme-dark-saas.alt-mode .themed-border { box-shadow: inset 0 1px 0 oklch(1 0 0 / 80%), var(--shadow-1); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }
